#include "Monstey_WorldSubmitContract.hpp"
#include <functional>
#include <iostream>
#include <limits>
using namespace Monstey;
namespace {
using A=std::uint64_t;using S=Monstey_WorldSubmitSnapshot;using J=Monstey_Json;
void Check(bool value){if(!value)throw std::runtime_error("World submit assertion failed");}
void Reject(const std::function<void()>& f){bool rejected=false;try{f();}catch(const Monstey_Error&){rejected=true;}Check(rejected);}
S Snap(A a,std::size_t n){return {a,Monstey_Bytes(n)};}
struct Fixture {
 Monstey_WorldModelSnapshots sources;S cull=Snap(0xA0000,48),model=Snap(0x60000,28),draw=Snap(0x70000,128),cached=Snap(0x80000,96),reference=Snap(0x90000,16),cachedSlot=Snap(0x91000,16);
 Fixture(){sources.context=Snap(0x10000,56);sources.wrapper=Snap(0x20000,32);sources.handle=Snap(0x30000,16);sources.slot=Snap(0x40000,16);sources.container=Snap(0x50000,16);Monstey_PutU64(sources.context.bytes,0,0x20000);Monstey_PutU64(sources.context.bytes,8,0xB0000);Monstey_PutU32(sources.context.bytes,16,1);Monstey_PutU64(sources.wrapper->bytes,0,0x30000);Monstey_PutU64(sources.handle->bytes,8,0x40000);Monstey_PutU64(sources.slot->bytes,8,0x50000);Monstey_PutU64(sources.container->bytes,0,0x60000);Monstey_PutU32(sources.container->bytes,8,1);Monstey_PutU64(cull.bytes,32,0x10000);cull.bytes[43]=1;cull.bytes[42]=4;Monstey_PutU64(model.bytes,0,0xC0000);Monstey_PutU64(model.bytes,16,0x70000);Monstey_PutU32(model.bytes,24,2);cached.bytes[56]=4;Monstey_PutU64(cached.bytes,32,0x90000);Monstey_PutU64(reference.bytes,8,0x91000);Monstey_PutU64(cachedSlot.bytes,8,0x60000);}
 Monstey_WorldModelResult Resolve()const{return Monstey_WorldResolveModel(sources);}
 Monstey_WorldGenericDrawResult Generic()const{return Monstey_WorldGenericDrawInspection(cull,sources.context,Resolve(),model,draw);}
 Monstey_WorldCachedGateResult Cached()const{return Monstey_WorldCachedGate(cached,reference,cachedSlot,model);}
};
}
int wmain(int argc,wchar_t** argv){try{if(argc!=2)throw std::runtime_error("Usage: WorldSubmitTests NEW-REPORT.json");Monstey_RequireOfflineOutput(argv[1]);J::Array passed;auto Test=[&](const char* n,const std::function<void()>& f){f();passed.push_back(n);};
Test("container_payload_is_distinct_from_model_record",[]{Fixture f;const auto r=f.Resolve();Check(r.container==0x50000&&r.model_array==0x60000&&r.model==0x60000&&r.context==0x10000&&r.ordinal_read&&r.count_read);});
Test("all65536_U16_ordinals_use_stride256_unsigned_compare",[]{Fixture f;Monstey_PutU32(f.sources.container->bytes,8,65536);for(unsigned i=0;i<65536;++i){Monstey_PutU16(f.sources.wrapper->bytes,24,static_cast<std::uint16_t>(i));const auto r=f.Resolve();Check(r.status==Monstey_WorldResolveStatus::Resolved&&r.model==0x60000+(static_cast<A>(i)<<8));}});
Test("ordinal_equality_zero_and_high_U32_count",[]{Fixture f;Monstey_PutU32(f.sources.container->bytes,8,0);auto r=f.Resolve();Check(r.native_hard_stop&&r.model==0);Monstey_PutU16(f.sources.wrapper->bytes,24,65535);Monstey_PutU32(f.sources.container->bytes,8,65535);Check(f.Resolve().native_hard_stop);Monstey_PutU32(f.sources.container->bytes,8,0xFFFFFFFF);Check(f.Resolve().status==Monstey_WorldResolveStatus::Resolved);});
Test("null_slot_reports_diagnostic_without_reading_ordinal_or_container",[]{Fixture f;Monstey_PutU64(f.sources.handle->bytes,8,0);f.sources.slot.reset();f.sources.container.reset();const auto r=f.Resolve();Check(r.status==Monstey_WorldResolveStatus::NullSlot&&r.diagnostic_45A24C&&!r.ordinal_read&&!r.count_read);Check(Monstey_WorldDescribeModel(r).at("ordinal_U16").is_null());});
Test("null_payload_does_not_resolve_a_model",[]{Fixture f;Monstey_PutU64(f.sources.slot->bytes,8,0);f.sources.container.reset();const auto r=f.Resolve();Check(r.status==Monstey_WorldResolveStatus::NullPayload&&!r.diagnostic_45A24C&&!r.ordinal_read&&r.model==0);});
Test("address_token_arithmetic_wraps_like_native_ADD",[]{Fixture f;Monstey_PutU64(f.sources.container->bytes,0,0xFFFFFFFFFFFFFF00);Monstey_PutU16(f.sources.wrapper->bytes,24,1);Monstey_PutU32(f.sources.container->bytes,8,2);Check(f.Resolve().model==0);});
Test("generic_flag_all256_is_zero_test_not_bit2",[]{Fixture f;for(unsigned i=0;i<256;++i){f.cull.bytes[43]=static_cast<std::uint8_t>(i);const auto r=f.Generic();Check(r.cull_flag==i&&r.selected_255920_generic_branch==(i==0)&&r.cull_mask==4);}});
Test("generic_draw_material_indices_and_arg7_selector_zero",[]{Fixture f;const auto r=f.Generic();Check(r.draw_count==2&&r.draw_in_range&&r.material_count==1&&r.material_slot==0&&r.material_in_range);Check(Monstey_U32(f.sources.context.bytes,48)==0);Check(r.draw_pointer==0x70000&&r.model_table0_pointer==0xC0000);});
Test("generic_draw_out_of_range_skips_draw_read",[]{Fixture f;Monstey_PutU16(f.cull.bytes,40,2);const auto r=Monstey_WorldGenericDrawInspection(f.cull,f.sources.context,f.Resolve(),f.model,{});Check(!r.draw_in_range&&r.draw_count==2);});
Test("generic_material_equal_bound_rejects_instead_of_clamping",[]{Fixture f;Monstey_PutU16(f.draw.bytes,54,1);const auto r=f.Generic();Check(r.draw_in_range&&!r.material_in_range&&r.material_slot==1);});
Test("all65536_U16_draw_and_material_values_preserve_full_width",[]{Fixture f;Monstey_PutU32(f.model.bytes,24,65536);Monstey_PutU32(f.sources.context.bytes,16,65536);for(unsigned i=0;i<65536;++i){Monstey_PutU16(f.cull.bytes,40,static_cast<std::uint16_t>(i));Monstey_PutU16(f.draw.bytes,54,static_cast<std::uint16_t>(i));f.draw.address=0x70000+static_cast<A>(i)*128;const auto r=f.Generic();Check(r.draw==i&&r.material_slot==i&&r.draw_in_range&&r.material_in_range);}});
Test("cached_all256_flags_test_only_bit2",[]{Fixture f;for(unsigned i=0;i<256;++i){f.cached.bytes[56]=static_cast<std::uint8_t>(i);const auto r=f.Cached();Check(r.bit2_enabled==((i&4)!=0));if(i&4)Check(r.slot_nonnull&&r.model_nonnull&&r.draw_in_range);}});
Test("cached_flag_gate_precedes_reference_access",[]{Fixture f;f.cached.bytes[56]=1;Monstey_PutU64(f.cached.bytes,32,0);const auto r=Monstey_WorldCachedGate(f.cached,{},{},{});Check(!r.bit2_enabled&&!r.slot_nonnull);});
Test("cached_slot_nonnull_is_not_payload_or_whole_readiness",[]{Fixture f;Monstey_PutU64(f.reference.bytes,8,0);auto r=Monstey_WorldCachedGate(f.cached,f.reference,{},{});Check(r.diagnostic_45A24C&&!r.model_nonnull);Monstey_PutU64(f.reference.bytes,8,0x91000);Monstey_PutU64(f.cachedSlot.bytes,8,0);r=Monstey_WorldCachedGate(f.cached,f.reference,f.cachedSlot,{});Check(r.slot_nonnull&&!r.model_nonnull&&!r.draw_in_range);});
Test("cached_unsigned_full_draw_count_boundary",[]{Fixture f;Monstey_PutU16(f.cached.bytes,58,65535);Monstey_PutU32(f.model.bytes,24,65536);Check(f.Cached().draw_in_range);Monstey_PutU32(f.model.bytes,24,65535);Check(!f.Cached().draw_in_range);});
Test("64B_source_entry38_is_pointer_not_flag_or_expanded_object",[]{auto e=Snap(0x100000,64);Monstey_PutU64(e.bytes,56,0x0000000187654321);Check(Monstey_WorldCachedEntryOwner(e)==0x0000000187654321);e.bytes.resize(63);Reject([&]{(void)Monstey_WorldCachedEntryOwner(e);});});
Test("source_address_mismatch_and_cross_context_results_reject",[]{Fixture f;f.sources.handle->address+=8;Reject([&]{(void)f.Resolve();});Fixture g;auto r=g.Resolve();r.context+=8;Reject([&]{(void)Monstey_WorldGenericDrawInspection(g.cull,g.sources.context,r,g.model,g.draw);});});
Test("every_selected_source_extent_truncation_rejects",[]{for(unsigned kind=0;kind<5;++kind){Fixture f;if(kind==0)f.sources.context.bytes.resize(55);if(kind==1)f.sources.wrapper->bytes.resize(25);if(kind==2)f.sources.handle->bytes.resize(15);if(kind==3)f.sources.slot->bytes.resize(15);if(kind==4)f.sources.container->bytes.resize(11);Reject([&]{(void)f.Resolve();});}Fixture f;f.cull.bytes.resize(47);Reject([&]{(void)f.Generic();});Fixture g;g.model.bytes.resize(27);Reject([&]{(void)g.Generic();});Fixture h;h.draw.bytes.resize(127);Reject([&]{(void)h.Generic();});Fixture i;i.cached.bytes.resize(95);Reject([&]{(void)i.Cached();});});
Test("unread_fields_are_null_not_fabricated_zero",[]{Fixture f;Monstey_PutU32(f.sources.container->bytes,8,0);const auto r=f.Resolve();Check(Monstey_WorldDescribeModel(r).at("resolved_model_record").is_null());const auto g=Monstey_WorldGenericDrawInspection(f.cull,f.sources.context,r,{},{});const auto j=Monstey_WorldDescribeGeneric(g);Check(j.at("model_nonnull").is_null()&&j.at("draw_count_U32").is_null()&&j.at("material_index_in_range").is_null());});
Test("source_bytes_and_result_lifetime_are_owned",[]{Fixture f;const auto before=f.sources.context.bytes;const auto r=f.Resolve();const auto json=Monstey_WorldDescribeModel(r);f.sources.context.bytes.assign(56,255);Check(json.at("context").as_string()=="0x0000000000010000");Check(r.wrapper==0x20000&&before[0]==0);Fixture g;const auto raw=g.cached.bytes;(void)g.Cached();Check(raw==g.cached.bytes);});
Monstey_WriteNewText(argv[1],J::object({{"schema","Monstey.WorldSubmitSyntheticTests/1"},{"pass",true},{"groups",passed},{"count",static_cast<A>(passed.size())},{"ordinal_cases",65536},{"draw_and_material_cases",65536},{"generic_flag_cases",256},{"cached_flag_cases",256},{"game_functions_called",false},{"game_memory_written",false}}).dump(2)+"\n");std::cout<<"PASS "<<passed.size()<<" World submit groups; all U16 ordinals/draws/materials and U8 flags\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}